def atom_ok(op, pat, w):
    if op=='match': return list(w)==list(pat)
    if op=='startswith': return list(w[:len(pat)])==list(pat)
    if op=='endswith': return list(w[len(w)-len(pat):])==list(pat) if len(w)>=len(pat) else False
    if op=='contains':
        p=list(pat); ww=list(w)
        if len(p)==0: return True
        for i in range(len(ww)-len(p)+1):
            if ww[i:i+len(p)]==p: return True
        return False

def ev(e,w):
    op=e['op']
    if op=='true': return True
    if op=='false': return False
    if op in ('match','startswith','endswith','contains'): return atom_ok(op,e['path'],w)
    if op=='not': return not ev(e['arg'],w)
    if op=='and': return all(ev(a,w) for a in e['args'])
    if op=='or': return any(ev(a,w) for a in e['args'])

